import{_ as a,o as t,c as l,a3 as r}from"./chunks/framework.Dj4Lt7vj.js";const _=JSON.parse('{"title":"兑换码","description":"","frontmatter":{"title":"兑换码"},"headers":[],"relativePath":"billing/redeem.md","filePath":"billing/redeem.md","lastUpdated":1787948622000}'),i={name:"billing/redeem.md"};function o(n,e,s,d,h,p){return t(),l("div",null,[...e[0]||(e[0]=[r('<h1 id="兑换码" tabindex="-1">兑换码 <a class="header-anchor" href="#兑换码" aria-label="Permalink to &quot;兑换码&quot;">​</a></h1><p>兑换码是目前最常用的开通方式：销售确认订单后发码给你，自助兑换即时到账。</p><h2 id="兑换步骤" tabindex="-1">兑换步骤 <a class="header-anchor" href="#兑换步骤" aria-label="Permalink to &quot;兑换步骤&quot;">​</a></h2><ol><li>打开客户端左侧菜单「账单」（或网页工作台的「账单」标签页）。</li><li>找到「兑换码」输入框。</li><li>输入销售提供的兑换码，点击兑换。</li><li>兑换成功后页面立即刷新，套餐或点数直接到账。</li></ol><h2 id="兑换须知" tabindex="-1">兑换须知 <a class="header-anchor" href="#兑换须知" aria-label="Permalink to &quot;兑换须知&quot;">​</a></h2><ul><li>兑换码<strong>不区分大小写</strong>，大小写输错了也能兑。</li><li>每个码只能兑换一次。</li><li>短时间内连续尝试多次会触发频率限制，稍等再试。</li><li>码可能对应套餐、也可能对应点数加油包，以购买时和销售确认的内容为准。</li></ul><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>提示兑换码无效？</strong> 逐字核对（注意数字 0 和字母 O、数字 1 和字母 l），确认没有多复制空格。核对无误仍失败的，找销售确认码的状态。</p><p><strong>提示已被使用？</strong> 兑换码只能用一次。如果你自己没兑过，联系销售核实。</p><p><strong>兑错账号了怎么办？</strong> 兑换直接作用于当前登录账号，无法自助转移。尽快联系销售处理。</p><p><strong>兑换的套餐什么时候生效？</strong> 兑换成功即生效，「账单」页顶部的套餐信息和可用点数会立即更新。</p>',11)])])}const m=a(i,[["render",o]]);export{_ as __pageData,m as default};
